  "propositions": [
    {"id": "P1", "text": "A tarifa zero no transporte público deve ser financiada com um percentual da arrecadação de impostos e contribuições financeiras de proprietários de veículos e empresários."},
    {"id": "P2", "text": "A tarifa zero no transporte público deve ser implementada por empresas públicas para evitar desvios de dinheiro e garantir transparência."},
    {"id": "P3", "text": "A tarifa zero no transporte público deve ser acompanhada de uma gestão controlada pelos usuários e trabalhadores através de conselhos populares."}
